N  = 2000

# Circles sorting in a non-decreasing order. Data are recovered in an array
A = np.zeros((N, 3))
A[0, :] = [r[0], theta[0], 0.0]
r[0] = 0
for n in range(1, N):
    index = indexmax(r)
    A[n, :] = [r[index], theta[index], index]
    r[index] = 0

def cercle(O:tuple, R:float, nb:int)->list:
    """
    Given a tuple O and a radius R, returns two arrays for each regular sampling coordinate on a circe with origin O and radius R.
    O (tuple) : circle center
    R (float) : circle radius
    nb (int) : number of steps
    """
    t = np.linspace(0, tau, nb)
    x = O[0] + R*np.cos(t)
    y = O[1] + R*np.sin(t)
    return [x, y]


def points(t:float, O = [r[0]*cos(theta[0]), r[0]*sin(theta[0])]):
    """
    Returns circle centers at date t.
    """
    # Axis 0 : points ; Axis 1 : coordinates
    P = np.zeros((N, 2))
    P[0, :]= O
    for n in range(1, N):
        P[n, 0] = P[n-1, 0] + A[n, 0]*np.cos(A[n, 1] + A[n, 2]*t)
        P[n, 1] = P[n-1, 1] + A[n, 0]*np.sin(A[n, 1] + A[n, 2]*t)
    return P

nb_images = 400
dt = tau/nb_images

plt.figure(figsize=(6.5, 8))
plt.xlim(-2250, 2000)
plt.ylim(-2250, 2000)

c = [0 for k in range(N)]
Pf = np.zeros((nb_images, 2))

t = 0
#plt.pause(60)
for i in range(nb_images):
    print(str(i) + '/' + str(nb_images))
    circles = [0]
    P = points(t)
    Pf[i, :] = P[-1, :]  # Dernier point, qui doit être sur la curve
    circles.append(cercle(P[0, :], A[1, 0], 50))
    for n in range(2, 10):
        circles.append(circle(P[n-1, :], A[n, 0], 20))
    for n in range(10, 100):
        circles.append(circle(P[n-1, :], A[n, 0], 10))
    for n in range(101, N):
        circles.append(circle(P[n-1, :], A[n, 0], 3))
    if i==0:
        plt.pause(60)
        for n in range(1, N-1):
            c[n], = plt.plot(circles[n][0], circles[n][1], lw=0.75, c='red')
            curve, = plt.plot(Pf[0, 0], Pf[0, 1], c='black')
    else:
        for n in range(1, N-1):
            c[n].set_xdata(cercles[n][0])
            c[n].set_ydata(cercles[n][1])
    curve.set_xdata(Pf[:i, 0])
    curve.set_ydata(Pf[:i, 1])
    plt.pause(0.001)
    t += dt

plt.show()